import random
from modules.byte_program import Capture,literal
import modules.capture_audit as ca
from modules.capture_audit import _field_block_fast,_field_block_slow,_ParseFailure
random.seed(321)
forb={b'host',b'x-a'}
for trial in range(10000):
 n=random.randrange(0,700)
 data=bytes(random.choice(b'abcXYZ: \t\r\n;!') for _ in range(n))
 cap=Capture([(None,literal(data))])
 def run(fn):
  try:return ('ok',fn(cap,0,0,forb))
  except _ParseFailure as e:return (e.kind,None)
 a=run(_field_block_fast);b=run(_field_block_slow)
 if a!=b:
  print('MISMATCH',trial,repr(data),a,b);break
else:print('field block match')
# parse fast/slow differential again including chunked/trailers
def parse(cap,fast):
 old=ca._header_block_fast
 if not fast: ca._header_block_fast=ca._header_block_slow
 try:
  try:return ('ok',ca._parse_request(cap,0,ca._AuditState()))
  except ca._ParseFailure as e:return (e.kind,None)
 finally:ca._header_block_fast=old
for trial in range(5000):
 prefix=random.choice([b'GET / HTTP/1.1\r\n',b'POST /x HTTP/1.1\r\n',b'GET  / HTTP/1.1\r\n'])
 n=random.randrange(0,300)
 hdr=bytes(random.choice(b'abcXYZ: \t\r\n;!') for _ in range(n))
 if random.random()<.7 and random.random()<.7:
  hdr += random.choice([b'\r\n',b'\r\n\r\n',b'Content-Length: 0\r\n\r\n',b'Transfer-Encoding: chunked\r\n\r\n0\r\n\r\n',b'Transfer-Encoding: chunked\r\n\r\n0\r\nHost: x\r\n\r\n',b'Transfer-Encoding: chunked\r\n\r\n0\r\nX:a\r\nX:a\r\n\r\n'])
 data=prefix+hdr+bytes(random.choice(b'ab\r\n012') for _ in range(random.randrange(20)))
 cap=Capture([(None,literal(data))])
 a=parse(cap,True);b=parse(cap,False)
 def sig(x):
  if x[1] is None:return None
  p=x[1][0];return (p.start,p.end,p.framing,p.host_count,p.body_fp,p.trailers_fp,p.headers_fp)
 if (a[0],sig(a))!=(b[0],sig(b)):
  print('PARSE MISMATCH',trial,repr(data),a[0],b[0]);break
else:print('parse match')
